FROM jsonb_populate_recordset(NULL::"ws_collections", $wychcombe_restore$[{"id":"0d4bfa84-5411-4bfd-a7b6-25fc82d44458","world_id":"wychcombe","name":"Victorian Garden Journals","season":null,"year":2026,"description":"The first WorldSmith product collection set within Wychcombe. Victorian Garden Journals translates the world’s botanical, archival, and stationery traditions into a coordinated collection of journal papers, cards, ephemera, and related components. Volume I begins with The Curator’s Desk and establishes the collection’s initial visual and production language.","status":"active","notion_page_id":null,"synced_at":null,"created_by":null,"created_at":"2026-08-30T21:10:21.141Z","updated_at":"2026-08-30T21:20:57.709Z"}]$wychcombe_restore$::jsonb)
