INSERT INTO "ws_canon_records" ("id", "world_id", "name", "status", "canon_type", "narrative_details", "historical_context", "visual_notes", "spec_ref_count", "notion_page_id", "synced_at", "created_by", "created_at", "updated_at", "emotional_register", "sensory_clauses", "register_locked", "narrative_visibility", "temporal_scope", "canon_stability", "from_entity_id", "to_entity_id", "emotional_valence", "portrait_url", "notes", "typography")
