FROM jsonb_populate_recordset(NULL::"ws_canon_record_relations", $wychcombe_restore$[{"from_record_id":"6a79b23a-ec8b-4398-bfef-2df1dcd5caea","to_record_id":"d2d2e2f5-bf2c-4c4e-a07d-33694f98d97d","relation_type":"related","created_at":"2026-08-19T03:18:49.025Z"},{"from_record_id":"6a79b23a-ec8b-4398-bfef-2df1dcd5caea","to_record_id":"0b22a708-24bf-4d5f-8550-b2fe7daae2e6","relation_type":"related","created_at":"2026-08-19T03:19:00.565Z"},{"from_record_id":"0d839e67-872f-4ad4-a42a-6c155c863ca0","to_record_id":"0b22a708-24bf-4d5f-8550-b2fe7daae2e6","relation_type":"related","created_at":"2026-08-19T03:17:18.429Z"},{"from_record_id":"0d839e67-872f-4ad4-a42a-6c155c863ca0","to_record_id":"2bd24482-d2c0-4ef9-a3a5-bc5fcc853672","relation_type":"related","created_at":"2026-08-19T03:19:17.501Z"},{"from_record_id":"6a79b23a-ec8b-4398-bfef-2df1dcd5caea","to_record_id":"0d839e67-872f-4ad4-a42a-6c155c863ca0","relation_type":"related","created_at":"2026-08-19T03:18:40.588Z"},{"from_record_id":"d2d2e2f5-bf2c-4c4e-a07d-33694f98d97d","to_record_id":"6a79b23a-ec8b-4398-bfef-2df1dcd5caea","relation_type":"related","created_at":"2026-08-19T21:24:10.188Z"},{"from_record_id":"0d839e67-872f-4ad4-a42a-6c155c863ca0","to_record_id":"6a79b23a-ec8b-4398-bfef-2df1dcd5caea","relation_type":"related","created_at":"2026-08-19T03:17:09.827Z"}]$wychcombe_restore$::jsonb)
